   paths.append(p)

def tables(data, base=0):
 if len(data)<base+12: return []
 num=struct.unpack('>H',data[base+4:base+6])[0]
 out=[]
 for i in range(num):
  rec=data[base+12+16*i:base+28+16*i]
  if len(rec)<16: break
  tag,chk,off,ln=struct.unpack('>4sIII',rec)
  out.append((tag,off,ln))
 return out
