  n=struct.unpack('>I',data[8:12])[0]
  bases=[struct.unpack('>I',data[12+4*i:16+4*i])[0] for i in range(n)]
 for base in bases:
  gs=[t for t in tables(data,base) if t[0] in [b'Silf',b'Glat',b'Gloc',b'Feat',b'Sill',b'Sile']]
  if gs:
   print(p, 'base',base, 'size',len(data), gs)
